import '@servicenow/sdk/global'
import { StringColumn } from '@servicenow/sdk/core'
import { Flow, wfa, action } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['flow_label_cache_action_outputs'],
        name: 'Flow Label Cache - Action Outputs',
        description: 'Tests label cache with action instance outputs as data pills',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
        flowVariables: {
            userId: StringColumn({
                mandatory: true,
                label: 'User ID',
                max_length: 32,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['label_cache_action_trigger'] },
        {
            table: 'sys_user',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Use OOB lookUpRecords action which has Count and Records outputs
        const lookupResult = wfa.action(
            action.core.lookUpRecords,
            { $id: Now.ID['lookup_users_step1'] },
            {
                table: 'sys_user',
                conditions: `sys_id=${wfa.dataPill(params.flowVariables.userId, 'string')}`,
                // limit: 1,
            }
        )

        // Use OOB createRecord action which has Record output
        const createResult = wfa.action(
            action.core.createRecord,
            { $id: Now.ID['create_record_step2'] },
            {
                table_name: 'task',
                values: `short_description=Found ${wfa.dataPill(lookupResult.Count, 'integer')} users`,
            }
        )

        // Log action using outputs from previous actions
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_step3'] },
            {
                log_message: `Created record: ${wfa.dataPill(createResult.record, 'string')}, Found: ${wfa.dataPill(lookupResult.Count, 'integer')}`,
                log_level: 'info',
            }
        )

        // Use action output in flow logic condition
        wfa.flowLogic.if(
            {
                $id: Now.ID['check_count_step4'],
                condition: `${wfa.dataPill(lookupResult.Count, 'integer')}>0`,
                annotation: 'Check if users found',
            },
            () => {
                // Another lookup to demonstrate chained outputs
                const chainedLookup = wfa.action(
                    action.core.lookUpRecords,
                    { $id: Now.ID['chained_lookup_step5'] },
                    {
                        table: 'task',
                        conditions: `sys_id=${wfa.dataPill(createResult.record, 'string')}`,
                        // limit: 1,
                    }
                )

                wfa.action(
                    action.core.log,
                    { $id: Now.ID['log_chained_step6'] },
                    {
                        log_message: `Records found: ${wfa.dataPill(lookupResult.Count, 'integer')}, Chained count: ${wfa.dataPill(chainedLookup.Count, 'integer')}`,
                        log_level: 'info',
                    }
                )
            }
        )
    }
)
